	if msg.Slug != "" {
		m.groupCache[msg.Slug] = cache.RegistryGroupEntry{
			Members:      toCachedMembers(msg.Members),
			DiscoveredAt: time.Now(),
		}
	}
	m.updateRegistryTable()
	return m, nil
}

